 export function fixedBlocksForDate(
   date: string,
   weekday: Weekday,
   fixedSchedule?: FixedSchedule | null,
 ): Block[] {
   const blocks: Block[] = (fixedSchedule?.weekdays?.[weekday] ?? []).map((block, index) => ({
     key: `fx-${date}-${index}`,
     title: block.title,
     startMin: hmToMin(block.start),
     endMin: hmToMin(block.end),
     tone: 'fixed',
   }));

   const sleep = fixedSchedule?.sleep;
   if (sleep) {
     const startMin = hmToMin(sleep.start);
     const endMin = hmToMin(sleep.end);
     if (startMin < endMin) {
       blocks.push({ key: `sleep-${date}`, title: '수면', startMin, endMin, tone: 'fixed', isSleep: true });
     } else if (startMin > endMin) {
       blocks.push(
         { key: `sleep-${date}-early`, title: '수면', startMin: 0, endMin, tone: 'fixed', isSleep: true },
         { key: `sleep-${date}-late`, title: '수면', startMin, endMin: 24 * 60, tone: 'fixed', isSleep: true },
