 /** 수면은 경계 1시간만 보이게 확장하고, 나머지 블록은 전체 범위를 표시한다. */
 export function timetableDisplayRange(
   blocksByDate: ReadonlyMap<string, readonly Block[]>,
 ): [number, number] {
   let lo = 7 * 60;
   let hi = 23 * 60;
   const sleepBlocks: Block[] = [];

   for (const list of blocksByDate.values()) {
     for (const block of list) {
       if (block.isSleep) {
         sleepBlocks.push(block);
