@@ -49,80 +49,104 @@ function explorationFamily(subject: string): 'science' | 'social' | null {

 function digestionSubjectKeys(subject: string, electives?: StudentElectives): string[] {
   const normalized = subject.trim();
   if (normalized === '탐구1' || normalized === '탐구2') return [normalized];
   const family = explorationFamily(normalized);
   if (family && electives) {
     const slots = [
       explorationFamily(electives.science_subject_1 ?? '') === family ? '탐구1' : null,
       explorationFamily(electives.science_subject_2 ?? '') === family ? '탐구2' : null,
     ].filter((slot): slot is string => slot !== null);
     if (slots.length > 0) return slots;
   }
   // 고1·고2처럼 탐구 슬롯이 아직 없을 때는 계열 키로 `과학` 강의와
   // `통합과학` 과제를 연결하면서, 기존 저장 계약의 기본 슬롯 별칭도 유지한다.
   if (family) {
     return [`family:${family}`, family === 'science' ? '탐구1' : '탐구2'];
   }
   return [normalized];
 }

 function digestionKeys(title: string, subject: string, electives?: StudentElectives): string[] {
   return digestionSubjectKeys(subject, electives).map(
     (subjectKey) => `${subjectKey}\u0000${title.trim()}`,
   );
 }

 /** 직접 등록 자료와 카탈로그 수강 등록을 소화량 카드의 단일 자료 목록으로 합친다. */
 export function registeredResourcesForDigestion(
   resources: DigestionResource[],
   enrollments: DigestionCourseEnrollment[],
 ): DigestionResource[] {
   const courses = enrollments.flatMap((enrollment) => {
     if (enrollment.status === 'dropped') return [];
     const course = first(enrollment.courses);
     const title = course?.title?.trim();
     if (!title) return [];
     const subject = first(course?.instructors)?.subject?.trim() ?? '';
     return [{ id: `course:${enrollment.id}`, kind: 'lecture' as const, subject, title }];
   });
   return [...resources, ...courses];
 }

 export function summarizeWeeklyDigestion(
   resources: DigestionResource[],
   tasks: DigestionTask[],
   electives?: StudentElectives,
 ): WeeklyDigestionRow[] {
   const rowsByResource = new Map<string, WeeklyDigestionRow>();
   const rows: WeeklyDigestionRow[] = [];
   for (const resource of resources) {
     const title = resource.title.trim();
     const keys = digestionKeys(title, resource.subject, electives);
     if (keys.some((key) => rowsByResource.has(key))) continue;
     const row = {
       ...resource,
       done: 0,
       total: 0,
       minutes: 0,
     };
     rows.push(row);
     for (const key of keys) rowsByResource.set(key, row);
   }

   for (const task of tasks) {
     const title = task.book?.trim();
     if (!title) continue;
     const row = digestionKeys(title, task.subject, electives)
       .map((key) => rowsByResource.get(key))
       .find((candidate) => candidate !== undefined);
     if (!row) continue;

     row.total += 1;
     if (task.status === 'completed') {
       row.done += 1;
       row.minutes += task.planned_min ?? 0;
     }
   }

   return rows.sort((a, b) => b.total - a.total);
 }
