+ * - error:   일부라도 실패 — "자료 없음"과 구분해 재시도를 유도한다.
+ * - empty:   등록 자료가 없음 — **숨기지 않고** 자리를 지키며 등록을 유도한다.
+ *            (예전엔 여기서 카드를 통째로 감춰 학생이 지표의 존재조차 몰랐다.)
+ * - list:    자료별 진행 목록.
+ */
+export type WeeklyDigestionCardState = 'pending' | 'error' | 'empty' | 'list';
+
+export function weeklyDigestionCardState({
+  loaded,
+  error,
+  rowCount,
+}: {
+  loaded: boolean;
+  error: boolean;
+  rowCount: number;
+}): WeeklyDigestionCardState {
+  if (!loaded) return 'pending';
+  if (error) return 'error';
+  return rowCount === 0 ? 'empty' : 'list';
+}

