 function kstNow(now: Date): { iso: string; min: number } {
   const k = new Date(now.getTime() + 9 * 3600000);
   return { iso: k.toISOString().slice(0, 10), min: k.getUTCHours() * 60 + k.getUTCMinutes() };
 }
