   132	                <span className="min-w-0 truncate font-semibold text-slate-700">{r.title}</span>
   133	                <span className="shrink-0 tabular-nums text-slate-400">
   134	                  {r.total === 0
   135	                    ? '미배정'
   136	                    : `${r.done}/${r.total}개${r.minutes > 0 ? ` · ${r.minutes}분` : ''}`}
   137	                </span>
   138	              </div>
   139	              <SegmentedProgressBar
   140	                percent={percent}
   141	                segments={10}
   142	                colorClass="bg-emerald-500"
   143	                className="mt-1"
   144	                ariaLabel={`${r.title} 소화율 ${percent}%`}
