   147	          );
   148	        })}
   149	      </ul>
   150	    </DigestionCardShell>
   151	  );
   152	}
   153	
   154	export default function WeeklyDigestionCard({
   155	  studentId,
   156	  electives,
   157	  onRegister,
   158	}: {
   159	  studentId: string;
   160	  electives?: StudentElectives;
   161	  /**
   162	   * 빈 상태 CTA — 같은 화면의 '교재·프린트 직접 등록' 모달을 연다.
   163	   * **필수**: 선택 프롭이면 배선이 조용히 빠져도 CTA가 사라진 채 초록으로 통과한다(#751 리뷰).
   164	   * 필수로 두면 배선 누락이 타입 에러로 잡힌다.
   165	   */
   166	  onRegister: () => void;
   167	}) {
   168	  const [tasks, setTasks] = useState<DailyTask[]>([]);
   169	  const [resources, setResources] = useState<DigestionResource[]>([]);
   170	  // loaded=아직 첫 조회 전(카드 렌더 보류). error=일부라도 실패해 최신 상태를 신뢰할 수 없음
   171	  // (예전엔 loaded 하나로 뭉뚱그려 실패도 "자료 없음"과 똑같이 카드를 숨겼다 — 등록 자료가
   172	  // 있는 학생이 일시적 네트워크 오류로 "자료 없음"처럼 보이는 문제, M4.7 폴리시).
   173	  const [loaded, setLoaded] = useState(false);
   174	  const [error, setError] = useState(false);
   175	  const [reloadKey, setReloadKey] = useState(0);
   176	  const [from, to] = useMemo(() => weekRange(kstTodayISO()), []);
   177	
   178	  useEffect(() => {
   179	    let alive = true;
   180	    (async () => {
   181	      setError(false);
   182	      try {
   183	        // 재방문 재요청 제거 — 20초→10분 상향. 완료 반영은 /today에서 이뤄지므로 최대 지연 10분.
   184	        const [taskRes, resourceRes, courseRes] = await Promise.all([
   185	          cachedFetch(
   186	            `/api/daily-tasks/range?from=${from}&to=${to}&student_id=${studentId}`,
   187	            { ttlMs: 10 * 60_000 },
   188	          ),
   189	          cachedFetch('/api/student-resources', { ttlMs: 10 * 60_000 }),
   190	          cachedFetch('/api/student-courses', { ttlMs: 10 * 60_000 }),
   191	        ]);
   192	        // 일부만 성공하면 등록 자료를 누락하거나 모두 미배정으로 오해할 수 있어 결과를 신뢰할
   193	        // 수 없다 — 조용히 숨기지 않고 에러 상태로 표시해 재시도를 유도한다.
   194	        if (!taskRes.ok || !resourceRes.ok || !courseRes.ok) throw new Error('일부 조회 실패');
   195	        const [taskJson, resourceJson, courseJson] = await Promise.all([
   196	          taskRes.json(),
   197	          resourceRes.json(),
   198	          courseRes.json(),
   199	        ]);
   200	        if (alive) {
   201	          setTasks(Array.isArray(taskJson.tasks) ? taskJson.tasks : []);
   202	          setResources(
   203	            registeredResourcesForDigestion(
   204	              Array.isArray(resourceJson.resources) ? resourceJson.resources : [],
   205	              Array.isArray(courseJson.enrolled)
   206	                ? (courseJson.enrolled as DigestionCourseEnrollment[])
   207	                : [],
   208	            ),
   209	          );
   210	        }
   211	      } catch {
   212	        if (alive) setError(true);
   213	      } finally {
   214	        if (alive) setLoaded(true);
   215	      }
   216	    })();
   217	    return () => {
   218	      alive = false;
   219	    };
   220	  }, [from, to, studentId, reloadKey]);
   221	
   222	  const rows = useMemo(
   223	    () => summarizeWeeklyDigestion(resources, tasks, electives),
   224	    [resources, tasks, electives],
   225	  );
   226	
   227	  // 로더는 뷰를 **조건 없이 한 번** 렌더한다 — 분기는 전부 WeeklyDigestionView 안에 있고
   228	  // 렌더 테스트가 그걸 지킨다(빈 상태를 조용히 감추는 회귀가 숨을 자리를 없앤다, #751 리뷰).
   229	  return (
   230	    <WeeklyDigestionView
   231	      state={weeklyDigestionCardState({ loaded, error, rowCount: rows.length })}
   232	      rows={rows}
   233	      onRegister={onRegister}
   234	      onRetry={() => setReloadKey((k) => k + 1)}
   235	    />
   236	  );
   237	}

