// lib/client-cache.ts — 클라이언트 읽기 요청용 경량 TTL 캐시(#21 F1).
// 목적: 자주 안 바뀌는 GET을 매 /today 진입마다 재요청하던 fan-out을 줄인다.
//
// ⚠️ 저장소 = sessionStorage: 이 앱의 네비게이션은 전역 <a href> = **전체 페이지 로드**라
//   모듈 스코프 Map은 매 로드마다 리셋돼 무효. sessionStorage는 탭 생명주기 동안
//   페이지 리로드를 넘어 유지되므로 재방문 시 캐시 적중 → 네트워크 재요청 제거.
//
// 적용 대상: 짧은 staleness를 허용하는 읽기 전용 GET(brand·exams·ranking 등).
//   ❌ daily-tasks(핵심·완료 시 변함)·notifications(폴링)에는 쓰지 말 것.
// `fetch(url, {cache:'no-store'})` 자리에 그대로 끼우는 드롭인(반환 타입 Response).
// ══════════════════════════════════════════════════════════════

const PREFIX = 'cf:';
const ANONYMOUS_NAMESPACE = 'anonymous';

interface Entry {
  body: string;
  status: number;
  ts: number;
}

/** 라이브 인증 사용자에 결박된 캐시 조회 결과. */
export interface AuthenticatedCacheRead<T> {
  /** getSession()으로 확인한 현재 사용자 ID. */
  userId: string;
  /** TTL 안의 캐시 본문. 미스·손상·만료면 null. */
  value: T | null;
  /** TTL 만료 시각. 캐시 미스면 null. */
  expiresAt: number | null;
}

/** sessionStorage 안전 접근(SSR/차단 환경에선 null → 캐시 우회). */
function storage(): Storage | null {
  try {
    if (typeof sessionStorage === 'undefined') return null;
    const candidate = sessionStorage;
    // 일부 브라우저/프라이버시 설정은 전역 객체 접근은 허용하지만 Storage API 사용 시점에
    // SecurityError를 던진다. 여기서 한 번 검증해 cache/dedup만 비활성화한다.
    void candidate.length;
    return candidate;
  } catch {
    return null;
  }
}

/** Storage API가 런타임에 차단되면 cache miss로만 처리한다. */
function readStorageItem(s: Storage, key: string): string | null {
  try {
    return s.getItem(key);
  } catch {
    return null;
  }
}

// in-flight 요청 dedup — 같은 URL을 (캐시 미스 상태에서) 동시에 호출하는 여러 컴포넌트가
// 한 번의 네트워크 요청을 공유하도록 fetch promise를 URL 키로 공유한다. (전역 <a href>
// 네비게이션은 전체 페이지 로드라 이 Map은 매 로드 리셋되지만, 같은 렌더에서 동시 마운트되는
// 컴포넌트들(예: 리포트의 뱃지 카드+월간 다이제스트가 같은 /api/parents/monthly 호출)의
// 중복 요청 제거에는 충분하다.) 모든 호출자에게는 clone을 반환해 body 소비 충돌을 막는다.
interface InflightEntry {
  response: Promise<Response>;
  valid: boolean;
}

const inflight = new Map<string, InflightEntry>();
// 한 요청 중 계정이 여러 번 바뀌어도 매 응답마다 namespace를 확인한다. 안정된 마지막
// 계정으로 정상 재시도할 여유는 주되, 끝없이 전환되면 검증 없는 최종 fetch를 보내지 않고
// fail-closed 한다. (A→B→C→D→E는 네 번의 재시도로 E까지 도달 가능)
const SESSION_TRANSITION_RETRY_LIMIT = 4;

/**
 * 요청이 진행되는 내내 인증 namespace가 안정되지 않았다는 뜻이다.
 * private 응답을 검증 없이 반환하는 것보다 호출자가 현재 세션에서 다시 로드하게 하는 편이
 * 안전하다. AuthIdentityBoundary의 remount는 이 오류가 사용자 화면에 남지 않는 2차 보호막이다.
 */
export class CacheSessionTransitionError extends Error {
  constructor() {
    super('인증 세션이 요청 중 여러 번 변경되어 응답을 안전하게 반환할 수 없습니다.');
    this.name = 'CacheSessionTransitionError';
  }
}

/**
 * 현재 인증 사용자를 캐시 namespace로 사용한다.
 *
 * URL만 키로 쓰면 같은 탭에서 A가 로그아웃하고 B가 로그인했을 때 A의 응답을 B가 읽을 수
 * 있다. getSession()은 브라우저의 Supabase 저장소를 읽으므로 네트워크 요청 없이 현재 사용자를
 * 확인한다. 세션을 안전하게 판별하지 못하면 캐시와 in-flight 공유를 모두 우회한다.
 */
async function currentCacheNamespace(): Promise<string | null> {
  try {
    const { createBrowserSupabase } = await import('@/lib/supabase');
    const {
      data: { session },
      error,
    } = await createBrowserSupabase().auth.getSession();
    if (error) return null;
    return session?.user.id ?? ANONYMOUS_NAMESPACE;
  } catch {
    return null;
  }
}

/** 비동기 읽기·mutation을 시작한 뒤에도 같은 인증 namespace가 유지되는지 확인한다. */
async function isCurrentNamespace(namespace: string): Promise<boolean> {
  return (await currentCacheNamespace()) === namespace;
}

function scopedKey(namespace: string, url: string): string {
  return `${PREFIX}${encodeURIComponent(namespace)}:${url}`;
}

function statusAllowsBody(status: number): boolean {
  return status !== 204 && status !== 205 && status !== 304;
}

/** namespace가 명시된 캐시 엔트리를 TTL까지 검증해 읽는다. */
function freshEntryForNamespace(url: string, ttlMs: number, namespace: string): Entry | null {
  const s = storage();
  if (!s) return null;
  const raw = readStorageItem(s, scopedKey(namespace, url));
  if (!raw) return null;
  try {
    const entry = JSON.parse(raw) as Entry;
    return Date.now() - entry.ts < ttlMs ? entry : null;
  } catch {
    return null;
  }
}

function urlFromCacheKey(key: string): string | null {
  if (!key.startsWith(PREFIX)) return null;
  const rest = key.slice(PREFIX.length);
  const separator = rest.indexOf(':');
  // 이전 URL-only 키도 invalidateCached()가 정리할 수 있게 유지한다.
  return separator === -1 ? rest : rest.slice(separator + 1);
}

/**
 * TTL 내면 sessionStorage의 캐시 응답을, 아니면 no-store로 새로 받아 캐시 후 반환.
 * 반환 타입이 Response라 기존 `const res = await fetch(...)` 코드에 드롭인.
 */
/**
 * 현재 인증 namespace를 다시 잡아 재시도한다.
 *
 * 절대 raw no-store fetch를 반환하지 않는다. retry cap에 닿은 뒤 검증 없는 응답을 한 번이라도
 * 반환하면 그 사이 다시 전환된 계정에 직전 사용자의 private body가 노출될 수 있기 때문이다.
 */
function retryForCurrentSession(
  url: string,
  opts: { ttlMs: number },
  transitionRetries: number,
): Promise<Response> {
  if (transitionRetries >= SESSION_TRANSITION_RETRY_LIMIT) {
    return Promise.reject(new CacheSessionTransitionError());
  }
  return cachedFetchForCurrentSession(url, opts, transitionRetries + 1);
}

/** 공개 API — private 응답은 인증 전환을 넘어서 반환하지 않는다. */
export function cachedFetch(url: string, opts: { ttlMs: number }): Promise<Response> {
  return cachedFetchForCurrentSession(url, opts, 0);
}

