 *
 * 동기 함수는 라이브 인증 세션을 확인할 수 없다. `cf-uid`는 마지막 cachedFetch의 계정일 뿐이라
 * A→B 같은 탭 전환에서 A 캐시를 B의 "신선함"으로 오인할 수 있다. 새 private UI는 반드시
 * hasFreshCacheForCurrentUser()를 await한다. 안전한 동기 인증 증명이 없으므로 보수적으로 false다.
 */
export function hasFreshCache(_url: string, _ttlMs: number): boolean {
  return false;
}

/**
 * 라이브 getSession()으로 확인한 현재 사용자 namespace에서만 TTL 신선도를 판정한다.
 *
 * private 카드의 스피너를 줄이는 용도다. sessionStorage의 마지막 사용자 마커는 절대 읽지 않아,
 * 계정 전환 후에는 안전하게 loading 상태로 들어간 뒤 현재 사용자 캐시/응답만 표시한다.
 */
export async function hasFreshCacheForCurrentUser(
  url: string,
  ttlMs: number,
): Promise<boolean> {
  const cached = await readFreshCacheForCurrentUser(url, ttlMs);
  return cached?.expiresAt !== null;
}

/**
 * TTL 내 신선한 캐시가 있으면 그 JSON 본문을 파싱해 동기 반환(네트워크·await 없음), 없으면 null.
 * hasFreshCache의 "값 반환" 버전 — 컴포넌트가 mount된 뒤 effect에서 지난 응답으로 UI를 즉시
 * 시드해 첫 페인트 팝인을 없앨 때 쓴다(예: 전역 코치 FAB 노출 판정, #573).
 *
 * ⚠️ 교차 사용자 안전은 caller가 넘기는 `expectedUid`(라이브 세션의 user id)로 보장된다.
 *   hasFreshCache/cachedFetch와 달리 이 함수는 sessionStorage의 'cf-uid' 마커를 신뢰하지 않는다.
 *   cf-uid는 마지막으로 cachedFetch를 호출한 사용자로 남는데, 같은 탭 계정 전환(A→B, 명시적
 *   로그아웃 없이)에선 이 마커가 이전 사용자(A)로 stale하게 남아 그걸 "현재 사용자"로 믿으면
 *   A의 판정을 B에 시드하게 된다(#636 리뷰 지적). 그래서 여기선 caller가 단언한 uid의
 *   namespace로만 조회한다 — 그 사용자가 직접 캐시한 항목이 아니면 절대 반환하지 않으므로
 *   구조적으로 교차 사용자 시드가 불가능하다. caller는 반드시 `getSession()`/onAuthStateChange로
 *   확인한 라이브 세션 uid를 넘겨야 한다(빈 문자열이면 시드 없음).
 * SSR hydration 중에는 sessionStorage를 볼 수 없으므로 useState initializer가 아니라 반드시
 *   effect 안에서만 호출한다(첫 렌더는 고정값으로 시작).
 */
export function readFreshCache<T = unknown>(
  url: string,
  ttlMs: number,
  expectedUid: string
): T | null {
  if (!expectedUid) return null;
  const entry = freshEntryForNamespace(url, ttlMs, expectedUid);
  if (!entry) return null;
  try {
    return JSON.parse(entry.body) as T;
  } catch {
    /* 손상된 캐시 항목 → 시드 없이 새로 fetch */
    return null;
  }
}

/**
 * 현재 로그인한 사용자 namespace로만 캐시를 읽는다.
 *
 * `cf-uid`는 마지막 cachedFetch의 사용자일 뿐, 로그인 전환 직후에는 이전 계정 값일 수 있다.
 * 표시 여부를 정하는 UI는 이 함수를 사용해 매번 getSession()으로 확인한 사용자 ID에만
 * 접근해야 한다. 비로그인 상태는 개인 응답을 시드하지 않도록 null을 반환한다.
 */
export async function readFreshCacheForCurrentUser<T = unknown>(
  url: string,
  ttlMs: number,
): Promise<AuthenticatedCacheRead<T> | null> {
  const userId = await currentCacheNamespace();
  if (!userId || userId === ANONYMOUS_NAMESPACE) return null;

  const entry = freshEntryForNamespace(url, ttlMs, userId);
  // Storage read와 JSON parsing 사이에는 await가 없지만, storage 접근 자체가 동기적으로
  // 길어질 수 있다. 반환 직전에 한 번 더 확인해 A cache의 freshness를 B의 것으로
  // 판정하지 않는다. 전환됐다면 보수적으로 miss로 처리한다.
  if (!(await isCurrentNamespace(userId))) return null;
  if (!entry) return { userId, value: null, expiresAt: null };
  try {
    return {
      userId,
      value: JSON.parse(entry.body) as T,
      expiresAt: entry.ts + ttlMs,
    };
  } catch {
    return { userId, value: null, expiresAt: null };
  }
}

/** 비동기 요청을 시작했던 사용자와 현재 라이브 세션이 여전히 같은지 확인한다. */
export async function isCurrentAuthenticatedCacheUser(userId: string): Promise<boolean> {
  return !!userId && await isCurrentNamespace(userId);
}

/** 현재 로그인한 사용자의 ID. 개인 mutation의 UI 반영 소유권을 고정할 때 사용한다. */
export async function getCurrentAuthenticatedCacheUserId(): Promise<string | null> {
  const userId = await currentCacheNamespace();
  return userId && userId !== ANONYMOUS_NAMESPACE ? userId : null;
}

/** prefix로 시작하는 캐시 항목 무효화(해당 리소스를 바꾸는 mutation 직후 호출). '' = 전체. */
export function invalidateCached(prefix: string): void {
  const s = storage();
  const toDelete: string[] = [];
  if (s) {
    try {
      for (let i = 0; i < s.length; i++) {
        const k = s.key(i);
        if (!k) continue;
        const cachedUrl = urlFromCacheKey(k);
        if (cachedUrl !== null && cachedUrl.startsWith(prefix)) toDelete.push(k);
      }
    } catch {
      // Storage가 런타임에 차단되면 persistent cache만 포기한다. 아래 in-flight 무효화는
      // 계속 수행해 mutation 이전 응답이 화면/캐시를 되덮지 못하게 한다.
    }
    for (const key of toDelete) {
      try {
        s.removeItem(key);
      } catch {
        /* Storage 차단 시 cache 삭제만 건너뜀 */
      }
    }
  }

  // mutation 전에 시작한 동일 리소스 GET을 새 호출자가 공유하거나, 완료 후 캐시에
  // 다시 기록하지 못하게 한다. Promise 자체는 기존 호출자에게 반환하되 캐시 수명만 끊는다.
  for (const [requestKey, entry] of inflight) {
    const requestedUrl = urlFromCacheKey(requestKey);
    if (requestedUrl !== null && requestedUrl.startsWith(prefix)) {
      entry.valid = false;
      if (inflight.get(requestKey) === entry) inflight.delete(requestKey);
    }
  }
}

/**
 * daily-task 완료/스킵/재생성 등 학습 진행 상태가 바뀐 직후 호출 — 그 상태에서 파생되는
 * 읽기 캐시들을 일괄 무효화한다. 캐싱으로 재로딩은 줄이되, 완료 직후 다른 탭(주간 타임테이블·
 * 리포트·관찰·월간·백로그·랭킹)에 최신 상태가 즉시 반영되도록(stale 방지).
