    77	// 강사 매칭 알고리즘 (특허 청구항 1 — 6항목 가중치)
    78	function calcMatchScore(profile: Props['profile'], grades: Props['grades']) {
    79	  if (!profile) return 72;
    80	  let score = 60;
    81	  const w = { focus:0.20, subject:0.25, style:0.20, target:0.15, exam:0.10, consent:0.10 };
    82	  if (profile.focus_minutes >= 90)     score += 20 * w.focus * 5;
    83	  else if (profile.focus_minutes >= 60) score += 20 * w.focus * 3.5;
    84	  else                                  score += 20 * w.focus * 1.5;
    85	  if (profile.math_subject) score += 25 * w.subject * 1.5;
    86	  if (profile.kor_subject)  score += 25 * w.subject * 0.8;
    87	  if (profile.study_style)  score += 20 * w.style * 2;
    88	  const gBonus: Record<string,number> = {
    89	    med: 1.6, sky: 1.5, seosunghan: 1.2, joongkyung: 1.0,
    90	    ewha_konkuk: 0.9, inseoul: 0.7, regional_natl: 0.6,
    91	    special: 0.8, etc: 0.5,
    92	    // 구버전 호환
    93	    med_top: 1.6, in_sky: 1.2, top10: 1.0, top30: 0.7,
    94	  };
    95	  score += 15 * w.target * (gBonus[profile.goal_university] || 0.8);
    96	  if (grades.length > 0) score += 10 * w.exam * 2;
    97	  return Math.min(97, Math.round(score));
    98	}
