import type { ReactNode } from 'react';

interface EmptyStateProps {
  /** 주 문구(필수). */
  title: string;
  /** 아이콘(이모지 또는 노드). 선택. */
  icon?: ReactNode;
  /** 보조 설명. 선택. */
  message?: string;
  /** 하단 액션 버튼 슬롯(예: 새로고침 버튼). 선택. */
  action?: ReactNode;
}

export default function EmptyState({ title, icon, message, action }: EmptyStateProps) {
  return (
    <div className="flex flex-col items-center justify-center rounded-xl border border-dashed border-slate-200 bg-slate-50/50 px-6 py-10 text-center">
      {icon && <div className="mb-2 text-2xl" aria-hidden="true">{icon}</div>}
      <p className="text-sm font-medium text-slate-500">{title}</p>
      {message && <p className="mt-1 text-xs text-slate-400">{message}</p>}
      {action && <div className="mt-4">{action}</div>}
    </div>
  );
}
async function requestMutation(url: string, init: RequestInit, failureMessage: string): Promise<void> {
  const response = await fetch(url, init);
  if (!response.ok) throw new Error(failureMessage);
}

export function patchStudentCourseProgress(id: string, progressPct: number): Promise<void> {
  return requestMutation(
    '/api/student-courses',
    {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        id,
        progress_pct: progressPct,
        status: progressPct >= 100 ? 'completed' : 'in_progress',
      }),
    },
    '저장 실패',
  );
}

export function deleteStudentCourse(id: string): Promise<void> {
  return requestMutation(
    `/api/student-courses?id=${encodeURIComponent(id)}`,
    { method: 'DELETE' },
    '삭제 실패',
  );
}

export function deleteStudentResource(id: string): Promise<void> {
  return requestMutation(
    `/api/student-resources?id=${encodeURIComponent(id)}`,
    { method: 'DELETE' },
    '삭제 실패',
  );
}

export function patchStudentResourceProgress(id: string, progress: string): Promise<void> {
  return requestMutation(
    '/api/student-resources',
    {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id, progress: progress.trim() || null }),
    },
    '저장 실패',
  );
}

export type InlineStudentResourceProgressResult =
  | { ok: true; progress: string | null }
  | { ok: false; error: string };

export async function saveInlineStudentResourceProgress(
  id: string,
  progress: string,
): Promise<InlineStudentResourceProgressResult> {
  const normalizedProgress = progress.trim() || null;
  try {
    await patchStudentResourceProgress(id, progress);
    return { ok: true, progress: normalizedProgress };
  } catch {
    return { ok: false, error: '진도를 저장하지 못했습니다. 다시 시도해 주세요.' };
  }
}
