/** KST 기준 월 (1~12). 서버 로컬 TZ 비의존. */
export function kstMonth(date: Date = new Date()): number {
  return kstCalendarParts(date).month;
}

/**
 * 오늘로부터 특정 날짜까지 남은 일수.
 * (KST 기준 자정 정렬)
 */
export function daysUntil(targetISO: string, today: Date = new Date()): number {
  const kstNow = new Date(today.getTime() + 9 * 60 * 60 * 1000);
  const todayStr = kstNow.toISOString().slice(0, 10);
  const t = new Date(`${todayStr}T00:00:00Z`).getTime();
  const target = new Date(`${targetISO}T00:00:00Z`).getTime();
  return Math.ceil((target - t) / 86400000);
}

/** 시험 이벤트 라벨 — courses.target_event(p79)와 동일 어휘. */
export type MockExamEvent = '6평' | '9평';

/** courses.target_event 전체 어휘(p89에서 '수능' 추가). */
export type ExamEvent = MockExamEvent | '수능';

/**
 * 현 학년도 기준 이미 지나간 모의평가 이벤트 목록.
 * "지난 시험 대비" 강좌를 추천에서 제외할 때 쓴다(p79 recommend RPC의
 * p_passed_events 인자). 날짜 판단의 단일 원천은 이 파일이다(골든룰 #1) —
 * SQL·라우트에 시험 날짜를 하드코딩하지 말 것.
 * 시험 당일(D-0)은 아직 지난 것으로 치지 않는다(직전 최종점검 수요).
 */
export function getPassedMockExams(
  schedule: ExamSchedule | null = getCurrentExamSchedule(),
  today: Date = new Date(),
): MockExamEvent[] {
  if (!schedule) return [];
  const passed: MockExamEvent[] = [];
  if (daysUntil(schedule.mockJune, today) < 0) passed.push('6평');
  if (daysUntil(schedule.mockSept, today) < 0) passed.push('9평');
  return passed;
}

/**
 * D-windowDays 이내로 다가온 시험 이벤트 목록 — getPassedMockExams와 쌍(p89).
 * "다가오는 시험 대비" 강좌 부스트(recommend RPC p_boost_events)에 쓴다.
 * 기본 45일: 평가원 대비 특강·모의고사 상품이 통상 시험 4~6주 전 개강 —
 * 30일이면 늦고 60일이면 6평 직후부터 9평 부스트가 걸려 기출 분석기를 침식.
 */
export function getUpcomingExamEvents(
  schedule: ExamSchedule | null = getCurrentExamSchedule(),
  today: Date = new Date(),
  windowDays = 45,
): ExamEvent[] {
  if (!schedule) return [];
  const out: ExamEvent[] = [];
  const dJune = daysUntil(schedule.mockJune, today);
  if (dJune >= 0 && dJune <= windowDays) out.push('6평');
  const dSept = daysUntil(schedule.mockSept, today);
  if (dSept >= 0 && dSept <= windowDays) out.push('9평');
  const dSu = daysUntil(schedule.suneung, today);
  if (dSu >= 0 && dSu <= windowDays) out.push('수능');
  return out;
}

/**
 * 페이즈 → 권장 학습 단계(courses.study_stage 어휘: 개념/유형/기출/실전).
 * 수강 이력이 없어 단계 추론이 안 되는 학생의 폴백(recommend RPC p_phase_stage).
 * ※ PHASE_KEY_TO_STUDY_PHASE(#213)는 학생 분류·교재용 "표시 문자열" 매핑이고,
 *   이 함수는 강좌 study_stage 컬럼 어휘 매핑 — 소비단이 다르다.
 */
export function phaseToStudyStage(key: PhaseKey): '개념' | '기출' | '실전' {
  if (key === 'concept') return '개념';
  if (key === 'analysis') return '기출';
  return '실전'; // realtime · finishing
}

/**
 * 입시판 표준 페이즈 — 6평·9평을 분기점으로 사용.
 *
 * 페이즈 1: 오늘 ~ 6평까지        (개념 보강)
 * 페이즈 2: 6평 ~ 9평             (기출 분석)
 * 페이즈 3: 9평 ~ 수능 D-30       (실전 적응)
 * 페이즈 4: 수능 D-30 ~ 수능      (마무리)
 *
 * N수생은 startEarly=true로 호출하면 "이미 기출 분석기" 등 단계가 앞당겨짐.
 */
export type PhaseKey = 'concept' | 'analysis' | 'realtime' | 'finishing';

export interface CurrentPhase {
  key: PhaseKey;
  /** 사람이 읽는 라벨 — "6평까지 (개념 보강)" 같은 형식 */
  label: string;
  /** 다음 분기점까지 남은 일수 */
  daysToNext: number;
  /** 다음 분기점 이름 — "6평", "9평", "수능D-30", "수능" */
  nextMilestone: string;
}

/**
 * #213 — 페이즈 판정 단일화. getCurrentPhase(6평·9평 앵커)가 유일한 "시기" 소스이고,
 * 교재 추천(phaseWeights)·학생 분류(study_phase) 소비단이 이 매핑으로 같은 값을 쓴다.
 * (기존엔 D-day 버킷 >120=개념을 각자 재계산해 6평 이후에도 '개념'으로 어긋났다.)
 */
export const PHASE_KEY_TO_STUDY_PHASE: Record<PhaseKey, string> = {
  concept: '개념 보강',
  analysis: '기출 분석',
  realtime: '실전 적응',
  finishing: '마무리',
};

export function getCurrentPhase(
  schedule: ExamSchedule,
  today: Date = new Date(),
  opts: { startEarly?: boolean } = {}
): CurrentPhase {
  const dJune = daysUntil(schedule.mockJune, today);
  const dSept = daysUntil(schedule.mockSept, today);
  const dSuneung = daysUntil(schedule.suneung, today);
  const d30 = dSuneung - 30;

  // N수생: 6평까지 60일 이상 남아도 이미 "기출 분석기"로 본다.
  // (재수종합반 통상 1~2월에 개념 1회독 종료, 3월부터 기출 진입)
  if (opts.startEarly && dJune > 60) {
    return {
      key: 'analysis',
      label: 'N수생 기출 분석기 — 6평까지',
      daysToNext: dJune,
      nextMilestone: '6평',
    };
  }

  if (dJune > 0) {
    return {
      key: 'concept',
      label: '개념 보강기 — 6평까지',
      daysToNext: dJune,
      nextMilestone: '6평',
    };
  }
  if (dSept > 0) {
    return {
      key: 'analysis',
      label: '기출 분석기 — 6평 ~ 9평',
      daysToNext: dSept,
      nextMilestone: '9평',
    };
  }
  if (d30 > 0) {
    return {
      key: 'realtime',
      label: '실전 적응기 — 9평 ~ 수능 D-30',
      daysToNext: d30,
      nextMilestone: '수능 D-30',
    };
  }
  return {
    key: 'finishing',
    label: '마무리기 — 수능 D-30 ~ 수능',
    daysToNext: Math.max(dSuneung, 0),
    nextMilestone: '수능',
  };
}

/**
 * 현재 시기(phase)의 짧은 라벨 — plan 뷰의 '진행중' 행 전용(#500).
 *
 * plan.phases[].name은 계획 생성 시점에 굳는다. 시간이 지나 6평을 통과하면 그 라벨이
 * 실제 현재 시기와 어긋나 '6평 대비' 같은 지난-시기 라벨이 화면에 남는다. 현재 행만
 * getCurrentPhase(라이브 6평·9평 앵커)로 다시 계산해 '지금'의 라벨을 보여준다.
 * 페이즈 판정 로직은 getCurrentPhase 단일 출처를 그대로 재사용하고(중복 금지),
 * 그 label("개념 보강기 — 6평까지")에서 앞의 시기명만 떼어 shortLabel과 같은 형식으로 만든다.
 */
export function getCurrentPhaseShortLabel(
  schedule: ExamSchedule,
  today: Date = new Date(),
  opts: { startEarly?: boolean } = {},
): string {
  return phaseLabelToShort(getCurrentPhase(schedule, today, opts).label);
}

