// - 계획 생성은 하지 않음 (조회 전용). 미래 날짜는 아직 task가 없을 수 있음.
// - from/to 미지정 시 최근 7일.
// ══════════════════════════════════════════════════════════════
import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabase';
import {
  requireUser,
  assertStudentAccess,
  AuthError,
  authErrorResponse,
} from '@/lib/auth';

/** 학생 ID 찾기 (학생 본인 세션 기준) */
async function findStudentId(userId: string): Promise<string> {
  const { data, error } = await supabaseAdmin
    .from('students')
    .select('id')
    .eq('user_id', userId)
    .maybeSingle();
  if (error || !data) {
    throw new AuthError(404, '학생 프로필이 없습니다');
  }
  return data.id;
}

const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function todayKST(): string {
  return new Date(Date.now() + 9 * 60 * 60 * 1000).toISOString().slice(0, 10);
}

export async function GET(req: NextRequest) {
  try {
    const user = await requireUser();

    const url = new URL(req.url);
    // student_id 생략 → 학생 본인. 명시 시 접근권 검증(self는 findStudentId가 소유권 보장).
    const paramStudentId = url.searchParams.get('student_id');
    const studentId = paramStudentId ?? (await findStudentId(user.id));
    if (paramStudentId) await assertStudentAccess(user.id, studentId, 'read');

    let from = url.searchParams.get('from') ?? '';
    let to = url.searchParams.get('to') ?? '';

    // 형식 검증 — 잘못된 값은 기본 범위(최근 7일)로 대체
    if (!DATE_RE.test(from) || !DATE_RE.test(to)) {
      const t = todayKST();
      const d = new Date(`${t}T00:00:00+09:00`);
      const start = new Date(d.getTime() - 6 * 86400000);
      from = start.toISOString().slice(0, 10);
      to = t;
    }
    // from > to면 스왑
    if (from > to) [from, to] = [to, from];

    const { data, error } = await supabaseAdmin
      .from('daily_tasks')
      .select(
        'id, date, subject, task_title, task_detail, book, status, completed, planned_min, start_time, end_time, source'
      )
      .eq('student_id', studentId)
      .gte('date', from)
      .lte('date', to)
      .order('date', { ascending: true })
      .order('order_index', { ascending: true });

    if (error) {
      console.error('[daily-tasks/range] fetch error:', error);
      throw new AuthError(500, '조회 실패');
    }

    return NextResponse.json({ from, to, tasks: data ?? [] });
  } catch (e) {
    return authErrorResponse(e);
  }
}

// lib/exam-calendar.ts
// ════════════════════════════════════════════════════════════
// 수능·6평·9평 시행일 상수 테이블.
//
// ※ 매년 1월 평가원 공식 발표 후 직접 갱신.
//   - 출처: 한국교육과정평가원 공식 일정, 메가스터디·EBSi 입시 캘린더
//   - 키: 학년도 (시행연도 = 학년도 - 1)
//   - 값: 6평 / 9평 / 수능 시행일 (KST 기준 YYYY-MM-DD)
//
// 사용처:
//   - generate-plan: 페이즈 분기점("6평까지", "9평~수능D-30")
//   - LongTermPlanView: 간트 차트 세로 마커
//   - milestone 자동 생성
// ════════════════════════════════════════════════════════════

export interface ExamSchedule {
  /** 학년도 (예: 2027 = 2026년 11월 시행 수능) */
  examYear: number;
  /** 6월 모의평가 (한국교육과정평가원 주관) */
  mockJune: string;
  /** 9월 모의평가 (한국교육과정평가원 주관) */
  mockSept: string;
  /** 본수능 */
  suneung: string;
  /** 날짜가 평가원·교육청에서 공식 발표된 경우에만 테이블에 넣는다. */
  status: 'confirmed';
}

/**
 * 학년도별 시험 일정 테이블.
 * - 2026 (2025-11): 확정 (시행 완료)
 * - 2027 (2026-11): 확정 (평가원 공식 발표, 2026년 1월)
 *
 * 2028·2029학년도는 아직 날짜가 공식 발표되지 않아 의도적으로 넣지 않는다.
 * 2028 개편 세대의 하반기 모의평가는 9월이 아닌 8월 체계지만, 시행일이 고시되기 전에는
 * 이 파일에 추정 날짜·D-day·페이즈 앵커를 만들지 않는다. 호출부는 null을 '발표 대기'로
 * 다뤄야 하며, 과거/다른 세대의 수능 일정으로 폴백해서는 안 된다.
 */
const SCHEDULE_TABLE: Record<number, ExamSchedule> = {
  2026: {
    examYear: 2026,
    mockJune: '2025-06-04',
    mockSept: '2025-09-03',
    suneung: '2025-11-13',
    status: 'confirmed',
  },
  2027: {
    examYear: 2027,
    mockJune: '2026-06-04',
    mockSept: '2026-09-02',
    suneung: '2026-11-19',
    status: 'confirmed',
  },
};

/**
 * 오늘 기준 "다음 수능"이 속한 학년도의 일정을 반환.
 * (수능일이 지났으면 다음 해 학년도로 자동 전환)
 */
export function getCurrentExamSchedule(today: Date = new Date()): ExamSchedule | null {
  // 학년도 오름차순으로 보면서, 수능일이 오늘보다 미래인 첫 항목 사용
  const years = Object.keys(SCHEDULE_TABLE)
    .map(Number)
    .sort((a, b) => a - b);
  for (const y of years) {
    const s = SCHEDULE_TABLE[y];
    // 시행 당일은 D-0으로 유지한다. UTC 자정 비교는 KST 오후에 하루를 너무 일찍 넘긴다.
    if (daysUntil(s.suneung, today) >= 0) return s;
  }
  // 다음 수능일이 아직 공식 발표되지 않았으면 과거 일정을 다음 일정처럼 쓰지 않는다.
  return null;
}

/**
 * 학년도로 직접 조회.
 */
export function getExamSchedule(examYear: number): ExamSchedule | null {
  return SCHEDULE_TABLE[examYear] ?? null;
}

/**
 * 오늘 기준 "다음 수능"까지 남은 일수 (D-day).
 * 공식 시행일 테이블(getCurrentExamSchedule)을 사용 — 하드코딩 금지.
 */
export function getSuneungDday(today: Date = new Date()): number | null {
  const schedule = getCurrentExamSchedule(today);
  return schedule ? daysUntil(schedule.suneung, today) : null;
}

/**
 * 특정 학년도(학생 본인의 수능) 기준 D-day. 테이블에 없으면 null.
 * (고1·2는 본인 학년도의 수능을 봐야 정확 — 다가오는 수능이 본인 것이 아님)
 */
export function getSuneungDdayForYear(examYear: number, today: Date = new Date()): number | null {
  const s = getExamSchedule(examYear);
  return s ? daysUntil(s.suneung, today) : null;
}

/**
 * 학생 학년(type) → 본인이 응시할 수능 학년도.
 *   고3·N수 = 다음 수능(기준), 고2 = +1년, 고1 = +2년.
 */
export function examYearForStudentType(
  studentType: 'high1' | 'high2' | 'high3' | 'nsu',
  today: Date = new Date(),
): number | null {
  const base = getCurrentExamSchedule(today)?.examYear; // 고3·N수가 보는 다음 수능
  if (base == null) return null;
  if (studentType === 'high2') return base + 1;
  if (studentType === 'high1') return base + 2;
  return base;
}

/**
 * 학생 학년 기준 수능 D-day. 고1·2도 "본인 학년도" 수능까지의 일수로 정확히 계산.
 * 본인 학년도의 공식 수능일이 아직 발표되지 않았으면 null.
 */
export function getSuneungDdayForStudentType(
  studentType: 'high1' | 'high2' | 'high3' | 'nsu',
  today: Date = new Date(),
): number | null {
  const y = examYearForStudentType(studentType, today);
  return y == null ? null : getSuneungDdayForYear(y, today);
}

/**
 * 학생 학년(type) 기준 "본인 수능" 일정. 고1·2는 다가오는 수능이 본인 것이 아니므로
 * getCurrentExamSchedule(다음 수능=고3·N수)를 그대로 쓰면 페이즈가 1~2년 앞선 잘못된
 * 앵커가 된다(#213 후속 — 고2가 D-383인데 '마무리기'로 판정되던 버그). 본인 학년도의
 * 공식 일정이 아직 없으면 null이며, 다른 세대·과거 일정으로 페이즈를 추정하지 않는다.
 */
export function getExamScheduleForStudentType(
  studentType: 'high1' | 'high2' | 'high3' | 'nsu',
  today: Date = new Date(),
): ExamSchedule | null {
  const examYear = examYearForStudentType(studentType, today);
  return examYear == null ? null : getExamSchedule(examYear);
}

