/** 마운트 상태의 추천 카드가 추천 입력 변경을 즉시 반영하도록 구독한다. */
export function subscribeRecommendationCacheInvalidation(
  listener: (source: RecommendationInvalidationSource) => void,
): () => void {
  recommendationInvalidationListeners.add(listener);
  return () => recommendationInvalidationListeners.delete(listener);
}

/** 추천 입력(성적·프로필·시험)이 바뀐 직후 강사/교재 추천을 함께 갱신한다. */
export function invalidateRecommendationCaches(
  source: RecommendationInvalidationSource = 'external',
): void {
  invalidateCached('/api/instructors/recommend');
  invalidateCached('/api/textbooks/recommend');
  for (const listener of recommendationInvalidationListeners) listener(source);
}

/** 학생 자료(교재·강의·프린트) 변경 후 목록과 그 입력에 의존하는 추천을 함께 갱신한다. */
export function invalidateStudentResourceCaches(): void {
  invalidateCached('/api/student-resources');
  invalidateRecommendationCaches();
}
