  type NaesinExamSubjectRpcInput,
} from '@/lib/naesin-exam-rpc';

async function findStudentId(userId: string): Promise<string> {
  const { data, error } = await supabaseAdmin
    .from('students')
    .select('id')
    .eq('user_id', userId)
    .maybeSingle();
  if (error) throw new AuthError(500, '학생 프로필 조회 실패');
  if (!data) throw new AuthError(404, '학생 프로필이 없습니다');
  return data.id;
}

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * YYYY-MM-DD 형태뿐 아니라 실제 달력에 존재하는 날짜인지 확인한다.
 * Date는 2월 30일 같은 값을 다음 달로 보정하므로, UTC 정오 파싱 뒤 원문과
 * 다시 비교해야 잘못된 기간으로 부모 시험만 저장되는 일을 막을 수 있다.
 */
function isValidIsoDate(date: string): boolean {
  if (!ISO_DATE.test(date)) return false;
  const parsed = new Date(`${date}T12:00:00Z`);
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === date;
}

const IsoDateSchema = z
  .string()
  .regex(ISO_DATE)
  .refine(isValidIsoDate, { message: '실제 달력 날짜여야 합니다.' });

export async function GET() {
  try {
    const user = await requireUser();
    const { data: student, error: studentError } = await supabaseAdmin
      .from('students')
      .select('id, type')
      .eq('user_id', user.id)
      .maybeSingle();
    if (studentError) throw new AuthError(500, '학생 프로필 조회 실패');
    if (!student) throw new AuthError(404, '학생 프로필이 없습니다');

    const { data, error: examsError } = await supabaseAdmin
      .from('naesin_exams')
      .select('id, title, start_date, end_date')
      .eq('student_id', student.id)
      .order('start_date', { ascending: true });
    if (examsError) throw new AuthError(500, '시험 일정 조회 실패');

    // 과목별 시험일(naesin_exam_subjects) 첨부 — 시험 시간표 기반 진로/융합 배치용.
    const exams = (data ?? []) as Array<Record<string, unknown>>;
    if (exams.length > 0) {
      const { data: subs, error: subjectsError } = await supabaseAdmin
        .from('naesin_exam_subjects')
        .select('exam_id, subject, exam_date, is_elective')
        .in('exam_id', exams.map((e) => e.id as string))
        .order('exam_date', { ascending: true });
      if (subjectsError) throw new AuthError(500, '과목별 시험 일정 조회 실패');
      const byExam = new Map<string, Array<{ subject: string; exam_date: string; is_elective: boolean }>>();
      for (const s of subs ?? []) {
        const arr = byExam.get(s.exam_id as string) ?? [];
        arr.push({ subject: s.subject as string, exam_date: s.exam_date as string, is_elective: !!s.is_elective });
        byExam.set(s.exam_id as string, arr);
      }
      for (const e of exams) e.subjects = byExam.get(e.id as string) ?? [];
    }

    // 학생 본인 학년도의 수능 D-day (네비에 표시)
    const ctx = gradeContext((student.type ?? 'high3') as StudentType);

    return NextResponse.json({
      exams,
      // 본인 학년도의 공식 일정만 사용한다. gradeContext의 고정 학년도만으로 과거
      // 수능 D-day를 되살리거나 미발표 다음 학년도를 추정하지 않는다.
      suneung_dday: getSuneungDdayForStudentType((student.type ?? 'high3') as StudentType),
      exam_year: ctx.examYear,
    });
  } catch (e) {
    return authErrorResponse(e);
  }
}

const PostSchema = z
  .object({
