  })
  .refine((v) => v.end_date >= v.start_date, { message: '종료일이 시작일보다 빠릅니다.' });

export async function POST(req: NextRequest) {
  try {
    const user = await requireUser();
    const studentId = await findStudentId(user.id);
    const parsed = PostSchema.safeParse(await req.json());
    if (!parsed.success) {
      return NextResponse.json({ error: '입력 형식 오류 (기간을 확인하세요)' }, { status: 400 });
    }
    const { title, start_date, end_date, subjects } = parsed.data;

    // 시험 기간 밖의 과목 시험일은 조용히 버리지 않고 400으로 거부한다(무음 삭제=가짜 성공 방지, GH#608 서버 방어).
    // 정상 UI는 클라이언트에서 먼저 막지만, 직접 API 호출·향후 UI 회귀에 대비한 서버측 게이트.
    const outOfRange = (subjects ?? []).filter(
      (s) => s.exam_date < start_date || s.exam_date > end_date,
    );
    if (outOfRange.length > 0) {
      return NextResponse.json(
        { error: `${outOfRange.length}개 과목의 시험일이 시험 기간 밖입니다. 날짜를 확인해주세요.` },
        { status: 400 },
      );
    }

    // p124 RPC 안에서 부모 시험과 모든 과목 행을 한 PostgreSQL 트랜잭션으로 저장한다.
    // 보상 삭제는 실패할 수 있으므로 절대 폴백하지 않는다. RPC가 실패하면 부모 행도
    // 커밋되지 않아 재시도가 중복 시험을 만들지 않는다.
    const subjectRows: NaesinExamSubjectRpcInput[] = (subjects ?? []).map((s) => ({
      subject: s.subject,
      exam_date: s.exam_date,
      is_elective: !!s.is_elective,
    }));
    const requestKey = naesinExamRequestKey({
      studentId,
      title,
      startDate: start_date,
      endDate: end_date,
      subjects: subjectRows,
    });
    const { data, error } = await supabaseAdmin.rpc('create_naesin_exam_with_subjects', {
      p_student_id: studentId,
      p_title: title,
      p_start_date: start_date,
      p_end_date: end_date,
      p_subjects: subjectRows,
      p_request_key: requestKey,
    });
    // RPC의 22023은 DB가 입력 계약을 거부했다는 뜻이다. DB 안전망을 통과하지
    // 못한 요청을 서버 장애(500)로 위장하지 않는다.
    if (error?.code === '22023') {
      return NextResponse.json({ error: '입력 형식 오류 (시험명·기간·과목을 확인하세요)' }, { status: 400 });
    }
    const exam = createdNaesinExamFromRpc(data);
    if (error || !exam) throw new AuthError(500, '저장 실패');

    return NextResponse.json({ exam: { ...exam, subjects: subjectRows } });
  } catch (e) {
    return authErrorResponse(e);
  }
}

export async function DELETE(req: NextRequest) {
  try {
    const user = await requireUser();
    const studentId = await findStudentId(user.id);
    const id = new URL(req.url).searchParams.get('id');
    if (!id) return NextResponse.json({ error: 'id 필수' }, { status: 400 });
    const { error } = await supabaseAdmin
      .from('naesin_exams')
      .delete()
      .eq('id', id)
      .eq('student_id', studentId); // 본인 것만
    if (error) throw new AuthError(500, '삭제 실패');
    return NextResponse.json({ ok: true });
  } catch (e) {
    return authErrorResponse(e);
  }
}
