 * 배열을 써서 순수 회귀 테스트에서도 탭 방문 이력을 그대로 검증할 수 있게 한다.
 */
export function visitRoadmapMode(
  visited: readonly RoadmapMode[],
  mode: RoadmapMode,
): RoadmapMode[] {
  return visited.includes(mode) ? [...visited] : [...visited, mode];
}

/**
 * 계획 트리는 항상 유지하고 비활성일 때만 화면·접근성 트리에서 숨긴다(SSR 시드·상태 보존).
 * 강사 강의 및 교재(resources) 탭은 자체 클라 조회가 있어 선택될 때만 마운트해
 * 초기 요청 fan-out을 늘리지 않는다(EP-54 패턴).
 */
export default function PersistentRoadmapModeContent({
  mode,
  plan,
  resources,
}: Props) {
  // 계획은 SSR 시드·상태 보존을 위해 언제나 마운트한다. 나머지는 첫 선택 때만 마운트한다.
  const [visitedModes, setVisitedModes] = useState<RoadmapMode[]>(() =>
    mode === 'plan' ? ['plan'] : ['plan', mode],
  );

  useEffect(() => {
    setVisitedModes((previous) => visitRoadmapMode(previous, mode));
  }, [mode]);

  const shouldRender = (panel: RoadmapMode) => panel === mode || visitedModes.includes(panel);

  const panelProps = (panel: RoadmapMode) => ({
    'data-roadmap-mode': panel,
    hidden: mode !== panel,
    'aria-hidden': mode !== panel,
    inert: mode !== panel ? true : undefined,
  });
  return (
    <>
      <div {...panelProps('plan')}>
        {plan}
      </div>
      {shouldRender('resources') && <div {...panelProps('resources')}>{resources}</div>}
    </>
  );
}
